suite chat.room {
    case "a stranger is refused" as integration {   // ✗ `refusedWith` below `system`
        let tc = TestConnection[Frame]()
        let _ <- Gateway.open(tc, Val[RoomId]) by Member(Val[UserId])
        expect tc.refusedWith() == Some(401)
    }
}

suite chat.room {
    case "a stranger is refused" as system {   // ✓ the Worker refuses the upgrade
        let tc = TestConnection[Frame]()
        let _ <- Gateway.open(tc, Val[RoomId]) by Nobody
        expect tc.refusedWith() == Some(401)
    }
}
